    { t:"1336-01-01", tur:"hukumdar", b:"İlhanlı Arpa Han, Şerefeddin Mahmud Şah İncû'yu öldürttü; dört oğlu arasında iktidar mücadelesi başladı (736 h./1336).", kaynak:"https://kureansiklopedi.com/tr/detay/inculular-2 (İncûlular maddesi)" },
    { t:"1338-07-20", tur:"ic-savas", b:"Kardeşler arasındaki mücadelede Gıyâseddin Keyhusrev öldü; Mesud, Şemseddin Muhammed'i Kal'a-i Sefîd'de hapsetti (739 h., mîlâdî yıl 1338-39; hicrî yılın ilk günü alındı).", kaynak:"https://kureansiklopedi.com/tr/detay/inculular-2 (İncûlular maddesi)" },
    { t:"1340-01-01", tur:"savas", b:"Çobanî Pîr Hüseyin, kurtulan Şemseddin Muhammed adına Şîraz'ı ele geçirdi ve onu öldürttü (740 h./1340).", kaynak:"https://kureansiklopedi.com/tr/detay/inculular-2 (İncûlular maddesi)" },
    { t:"1343-01-01", tur:"ic-savas", b:"Mesud Şah, Yağıbastı'nın desteğiyle Şîraz'a girdi ancak öldürüldü; Şîraz'da Ebû İshak'ın hâkimiyeti pekişti (743 h./1343).", kaynak:"https://kureansiklopedi.com/tr/detay/inculular-2 (İncûlular maddesi)" },
    { t:"1350-03-11", tur:"savas", b:"Ebû İshak Yezd'i dört ay kuşattı, kış yaklaşınca kuşatmayı kaldırıp Şîraz'a döndü (751 h./1350; hicrî yılın ilk günü alındı).", kaynak:"https://kureansiklopedi.com/tr/detay/inculular-2 (İncûlular maddesi)" },
    { t:"1352-02-18", tur:"savas", b:"Ebû İshak'ın Kirman'a saldırısı ağır kayıplarla sonuçlandı (753 h./1352; hicrî yılın ilk günü alındı).", kaynak:"https://kureansiklopedi.com/tr/detay/inculular-2 (İncûlular maddesi)" },
    { t:"1353-02-06", tur:"toprak-kayip", b:"Muzafferî Mübârizüddin, Şîraz halkının kapıları açmasıyla şehri aldı; Ebû İshak İsfahan'a, oradan Luristan'a çekildi (754 h./1353; hicrî yılın ilk günü alındı).", kaynak:"https://kureansiklopedi.com/tr/detay/inculular-2 (İncûlular maddesi)" },
    { t:"1357-01-01", tur:"son", b:"Muzafferî Mübârizüddin Muhammed Şiraz'ı alıp son İncû hükümdarı Ebû İshak'ı ortadan kaldırdı", ic_not_b:"eski b: Muzafferî Mübârizüddin Muhammed Şiraz'ı alıp son İncû hükümdarı Ebû İshak'ı ortadan kaldırdı (bkz. [[muzafferi]])" }
