    { t:"1862-07-04", tur:"siyaset", b:"Binbaşı Evans Owens Vadisi'nde Camp Independence karargâhını kurdu.", kaynak:"HistoryNet, War Drums in Owens Valley: https://historynet.com/war-drums-owens-valley/" },
    { t:"1862-10-06", tur:"antlasma", b:"Wasson'ın Camp Independence'taki konseyinde savaşan taraflar barış antlaşmasını imzaladı.", kaynak:"HistoryNet, War Drums in Owens Valley: https://historynet.com/war-drums-owens-valley/" },
    { t:"1863-01-01", tur:"toprak-kayip", b:"Owens Vadisi savaşı sona erdi; Payutlar Fort Tejon'a sürüldü" },
    { t:"1863-05-22", tur:"siyaset", b:"Owens Vadisi Payut önderi Kaptan George yaklaşık 400 adamıyla teslim oldu.", kaynak:"HistoryNet, War Drums in Owens Valley: https://historynet.com/war-drums-owens-valley/" },
    { t:"1872-01-01", tur:"toprak-kayip", b:"Malheur Rezervasyonu kuruldu" }
