    { t:"1381-08-15", tur:"siyaset", b:"Konstantin Dragaš (Dejanović) Lesnovo Manastırı'nı Hilandar'a bağışladı; Doğu Makedonya'nın mutlak efendisi olarak sürdü.", kaynak:"D. Popović, Zbornik Instituta za Balkanske studije, https://xn--cdaaa.doiserbia.nb.rs/img/doi/0350-7653/2019/0350-76531950039P.pdf (arama özeti; metin doğrudan okunmadı)" },
    { t:"1392-02-10", tur:"ittifak", b:"Konstantin Dejanović'in kızı Jelena (Helena Dragaş), Bizans İmparatoru II. Manuel Palaiologos ile evlendi; ertesi gün taç giydiler.", kaynak:"D. M. Nicol, Byzantium and Venice: A Study in Diplomatic and Cultural Relations, Cambridge 1988, s. 331 (aktaran: en.wikipedia 'Konstantin Dejanović' dipnotu)" },
    { t:"1395-05-17", tur:"son", b:"Rovine Savaşı'nda Konstantin Dejanović Osmanlı saflarında savaşırken öldü, toprakları doğrudan Osmanlı idaresine geçti", kaynak:"künyenin kendi ozet alanı — DOĞRULANMADI, künyenin kendi notu 'ARANMAYA DEVAM' diyor" }
