    { t:"1956-09-19", tur:"kurulus", b:"Amílcar Cabral ve arkadaşları Bissau'da PAIGC'yi kurdu.", kaynak:"Encyclopaedia Britannica, African Independence Party for Guinea and Cape Verde, https://www.britannica.com/topic/African-Independence-Party-for-Guinea-and-Cape-Verde" },
    { t:"1959-08-03", tur:"felaket", b:"Pidjiguiti rıhtım grevinde PIDE ateş açtı, en az 25 işçi öldü; PAIGC mücadeleyi kırsala ve gerilla yöntemine kaydırdı.", kaynak:"Encyclopaedia Britannica, Guinea-Bissau, https://www.britannica.com/place/Guinea-Bissau/Independence ; Pidjiguiti massacre, https://en.wikipedia.org/wiki/Pidjiguiti_massacre" },
    { t:"1963-01-23", tur:"isyan", b:"PAIGC Ocak 1963'te silâhlı bağımsızlık mücadelesini başlattı.", kaynak:"Encyclopaedia Britannica, Guinea-Bissau, https://www.britannica.com/place/Guinea-Bissau/Independence" },
    { t:"1973-01-20", tur:"siyaset", b:"PAIGC lideri Amílcar Cabral Konakri'de Inocêncio Kani tarafından öldürüldü.", kaynak:"Encyclopaedia Britannica, Amilcar Lopes Cabral, https://www.britannica.com/biography/Amilcar-Lopes-Cabral" },
    { t:"1973-09-24", tur:"isyan", b:"PAIGC Gine Bissau'nun bağımsızlığını ilan etti", kaynak:"TDV: gine-bissau" },
    { t:"1974-04-25", tur:"siyaset", b:"Portekiz'de Nisan 1974 darbesi (Karanfil Devrimi) sömürge savaşını bitirip bağımsızlık müzakerelerinin yolunu açtı.", kaynak:"Encyclopaedia Britannica, Guinea-Bissau, https://www.britannica.com/place/Guinea-Bissau/Independence" }
