    { t:"1197-11-13", tur:"hukumdar", b:"Zengî'nin halefi Tekle yaklaşık yirmi yıllık saltanatın ardından öldü; kardeşi Sa'd b. Zengî veraset mücadelesini kazanıp tahta çıktı (594 h., mîlâdî yıl 1197-98; hicrî yılın ilk günü alındı).", kaynak:"https://www.iranicaonline.org/articles/atabakan-e-fars-princes-of-the-salghurid-dynasty-who-ruled-fars-in-the-6th-12th-and-7th-13th-centuries-initially-with-/ (Encyclopaedia Iranica, Atābakān-e Fārs)" },
    { t:"1217-04-10", tur:"savas", b:"Sa'd b. Zengî kuzeye yürüyüp Rey, Kazvin ve Semnan'ı işgal etti; Rey yakınında Hârizmşah'a yenilip esir düştü ve haraca bağlandı (614 h./1217; hicrî yılın ilk günü alındı).", kaynak:"https://www.iranicaonline.org/articles/atabakan-e-fars-princes-of-the-salghurid-dynasty-who-ruled-fars-in-the-6th-12th-and-7th-13th-centuries-initially-with-/ (Encyclopaedia Iranica, Atābakān-e Fārs); https://islamansiklopedisi.org.tr/salgurlular (TDV, Salgurlular)" },
    { t:"1226-01-01", tur:"hanedan", b:"Sa'd b. Zengî öldü; Ebû Bekir tahta geçip Ögedey Han'a itaatini bildirdi", kaynak:"salgurlular" },
    { t:"1260-05-18", tur:"hukumdar", b:"Moğollara itaat etmiş olan Atabeg Ebû Bekir b. Sa'd öldü (5 Cemâziyelâhir 658).", kaynak:"https://www.iranicaonline.org/articles/atabakan-e-fars-princes-of-the-salghurid-dynasty-who-ruled-fars-in-the-6th-12th-and-7th-13th-centuries-initially-with-/ (Encyclopaedia Iranica, Atābakān-e Fārs)" },
    { t:"1262-11-20", tur:"hukumdar", b:"Sa'd'ın kısa süren hükümdarlığından sonra tahta çıkan I. Muhammed öldü (6 Muharrem 661).", kaynak:"https://www.iranicaonline.org/articles/atabakan-e-fars-princes-of-the-salghurid-dynasty-who-ruled-fars-in-the-6th-12th-and-7th-13th-centuries-initially-with-/ (Encyclopaedia Iranica, Atābakān-e Fārs)" },
    { t:"1264-12-04", tur:"hukumdar", b:"Selçukşah Kâzerûn önünde idam edildi (12 Safer 663); ardından Fars'ta Abiş Hatun dönemi başladı.", kaynak:"https://www.iranicaonline.org/articles/atabakan-e-fars-princes-of-the-salghurid-dynasty-who-ruled-fars-in-the-6th-12th-and-7th-13th-centuries-initially-with-/ (Encyclopaedia Iranica, Atābakān-e Fārs)" },
    { t:"1272-07-29", tur:"siyaset", b:"Abiş Hatun, Hülâgû'nun oğlu Möngke Temür ile evlendirildi; Salgurlu hanedanı İlhanlı hanedanıyla akrabalık kurdu (671 h./1272; hicrî yılın ilk günü alındı).", kaynak:"https://www.iranicaonline.org/articles/atabakan-e-fars-princes-of-the-salghurid-dynasty-who-ruled-fars-in-the-6th-12th-and-7th-13th-centuries-initially-with-/ (Encyclopaedia Iranica, Atābakān-e Fārs)" }
