    { t:"1153-08-23", tur:"toprak-kazanc", b:"III. Baldwin Fâtımîlerin elindeki Askalan'ı (Ascalon) teslim aldı; Filistin kıyısındaki son Müslüman limanı krallığa katıldı.", kaynak:"Britannica, 'Baldwin III' (Ağustos 1153); gün: Timeline of the Kingdom of Jerusalem (Wikipedia)" },
    { t:"1187-07-04", tur:"savas", b:"Hıttîn Muharebesi: Selâhaddîn-i Eyyûbî Tiberya Gölü yakınında Kudüs ordusunu ezdi; Kral Guy de Lusignan ve Renaud de Châtillon esir düştü, krallığın saha ordusu yok oldu.", kaynak:"Belleten (Türk Tarih Kurumu) makalesi, belleten.gov.tr/tam-metin/2146/tur: '4 Temmuz 1187 Cumartesi' Hıttîn zaferi; Timeline of the Kingdom of Jerusalem (Wikipedia)" },
    { t:"1187-10-02", tur:"toprak-kayip", b:"İbelinli Balian, kuşatma altındaki Kudüs'ü Selâhaddîn'e teslim etti; Haçlıların 88 yıllık Kudüs hâkimiyeti sona erdi, krallık Sur-Akkâ kıyı şeridine sıkıştı.", kaynak:"Encyclopedia.com, Columbia Encyclopedia 'Jerusalem, Latin Kingdom of' (1187); Belleten makalesi (belleten.gov.tr/tam-metin/2146/tur): Balian'ın 2 Ekim 1187 teslimi" },
    { t:"1192-09-02", tur:"antlasma", b:"III. Haçlı Seferi'ni bitiren Yafa ateşkesi: Aslan Yürekli Richard ile Selâhaddîn üç yıllık barış yaptı; Kudüs Müslümanlarda kaldı, Haçlılar Sur-Yafa arası kıyı şeridini korudu, hacılara serbest ziyaret tanındı.", kaynak:"WJEC, 'The Third Crusade' (resource.download.wjec.co.uk): 2 Eylül 1192; Treaty of Jaffa (1192) (Wikipedia, 1-2 Eylül)" },
    { t:"1229-02-18", tur:"antlasma", b:"II. Friedrich ile Eyyûbî Sultanı el-Kâmil arasında imzalanan Yafa Antlaşması (VI. Haçlı Seferi) Kudüs şehrini on yıllık ateşkesle krallığa geri verdi; Harem bölgesi Müslümanlarda kaldı.", kaynak:"Treaty of Jaffa (1229) (Wikipedia, 18 Şubat 1229); Columbia Encyclopedia, 'Jerusalem, Latin Kingdom of' (1229)" },
    { t:"1244-01-01", tur:"toprak-kayip", b:"Harizmli askerler Kudüs'ü ele geçirip yağmaladı; şehir Haçlıların elinden kalıcı olarak çıktı (kaynaklar Temmuz/Ağustos 1244 arasında ayrışır; gün belirlenemedi, yıl düzeyinde).", kaynak:"Columbia Encyclopedia, 'Jerusalem, Latin Kingdom of' (1244); Linda Paterson, Singing the Crusades, Boydell & Brewer 2018, böl. 10 (Cambridge Core, DOI 10.1017/9781787442092.013): 11 Ağustos 1244" },
    { t:"1244-10-17", tur:"savas", b:"La Forbie (Harbiyye) Muharebesi: Harizmlilerle birleşen Mısır ordusu Haçlı-Şam ittifakı ordusunu yok etti; Kudüs krallığı toparlanamaz biçimde zayıfladı.", kaynak:"Linda Paterson, Singing the Crusades, Boydell & Brewer 2018, böl. 10 (Cambridge Core, DOI 10.1017/9781787442092.013): 17 Ekim" },
    { t:"1291-05-18", tur:"son", b:"Memlükler Akkâ'yı fethetti; Kudüs Krallığı sona erdi", kaynak:"TDV: haclilar", taraflar:"['kudus-kralligi', 'memluk']", gun:"18 Mayıs 1291", ic_not_t:"1281 sonrası — kuşak dışı, yalnız künye iskeleti" }
