    { t:"1087-09-09", tur:"bolunme", b:"Fatih Guillaume ölür; Normandiya oğlu Robert Courteheuse'e, İngiltere ise William Rufus'a kalır ve dükalık İngiltere'den ayrılır.", kaynak:"Britannica, 'William I'; Britannica, 'Robert II Curthose'" },
    { t:"1106-09-28", tur:"savas", b:"Tinchebray Savaşı: İngiltere kralı I. Henry, ağabeyi Robert Courteheuse'ü yenip esir alır ve Normandiya'yı fetheder.", kaynak:"Wikipedia 'Battle of Tinchebray' https://en.wikipedia.org/wiki/Battle_of_Tinchebray ; Anglo-Saxon Chronicle (s.a. 1106); Britannica, 'Henry I'" },
    { t:"1135-12-01", tur:"hukumdar", b:"I. Henry ölür; Blois'lı Étienne Normandiya'yı ve İngiltere'yi devralır, Matilda ile Anjou kontu Geoffroy karşı çıkar.", kaynak:"Britannica, 'Henry I'; Britannica, 'Stephen'" },
    { t:"1144-01-19", tur:"isgal", b:"Anjou kontu Geoffroy Plantagenêt Rouen'e girer ve Normandiya'nın fethini tamamlar.", kaynak:"Britannica, 'Geoffrey V Plantagenet'; D. Crouch, The Normans (2002)" }
