    { t:"2009-09-07", tur:"siyaset", b:"Samoa trafikte sağdan sola geçerek yarım yüzyıla yakın sürede yol tarafını değiştiren ilk ülke oldu; amaç Avustralya ve Yeni Zelanda'dan ikinci el araç ithalatını kolaylaştırmaktı.", kaynak:"https://www.aljazeera.com/news/2009/9/7/samoa-set-to-switch-road-lanes ; https://www.jalopnik.com/2229382/samoa-switch-to-driving-on-the-left-2009-used-car-imports/" },
    { t:"2011-12-30", tur:"siyaset", b:"Samoa tarih değiştirme çizgisinin batısına geçti: 29 Aralık Perşembe'den doğrudan 31 Aralık Cumartesi'ne atlandı, 30 Aralık günü yaşanmadı.", kaynak:"https://www.timeanddate.com/news/time/tokelau-dateline.html ; https://mg.co.za/?p=139790" },
    { t:"2021-07-23", tur:"siyaset", b:"Temyiz Mahkemesi, 24 Mayıs'taki çadır yemin töreninin anayasaya uygun olduğuna ve yasal hükümetin FAST partisi olduğuna karar verdi; Fiame Naomi Mataʻafa ilk kadın başbakan oldu, Tuilaʻepa 26 Temmuz'da yenilgiyi kabul etti.", kaynak:"https://www.jurist.org/news/2021/07/samoa-high-court-declares-inauguration-legal-confirms-first-female-prime-minister ; https://www.kpbs.org/news/2021/07/23/samoan-court-clears-the-way-for-the-nations-1st" }
